javascript:(function(){if(window.__rt_active){window.__rt_cleanup&&window.__rt_cleanup();return;}window.__rt_active=1;var store={items:[],phase:'baseline'};function cssPath(el){if(!(el instanceof Element))return'';var parts=[],cur=el;while(cur&&cur.nodeType===1&&cur!==document.body&&cur!==document.documentElement){var seg=cur.tagName.toLowerCase();if(cur.id){parts.unshift('#'+cur.id);break;}var cls=(cur.getAttribute('class')||'').trim().split(/\s+/).filter(Boolean);if(cls.length){seg='.'+cls.join('.');}var parent=cur.parentElement;if(parent){var idx=Array.prototype.indexOf.call(parent.children,cur)+1;var sameType=Array.prototype.filter.call(parent.children,function(c){if(cls.length){var ccls=(c.getAttribute('class')||'').trim().split(/\s+/).filter(Boolean);return ccls.join('.')===cls.join('.');}return c.tagName===cur.tagName;});if(sameType.length>1){seg+=':nth-child('+idx+')';}}parts.unshift(seg);cur=cur.parentElement;}return parts.join(' ');}function accName(el){return(el.getAttribute('aria-label')||'').trim()||(function(){var lb=el.getAttribute('aria-labelledby');if(lb){var r=document.getElementById(lb.split(/\s+/)[0]);if(r)return(r.textContent||'').trim();}return'';})();}function landmark(el){var lm={nav:'Navigation',header:'Banner',footer:'Contentinfo',main:'Main',aside:'Complementary',form:'Form',search:'Search'};var roleMap={navigation:'Navigation',banner:'Banner',contentinfo:'Contentinfo',main:'Main',complementary:'Complementary',form:'Form',search:'Search',region:'Region'};var cur=el,hops=0;while(cur&&cur.nodeType===1&&hops<12&&cur!==document.body){var t=cur.tagName.toLowerCase();var role=(cur.getAttribute('role')||'').toLowerCase();var name=null;if(role&&roleMap[role])name=roleMap[role];else if(lm[t]){if((t==='header'||t==='footer')&&cur.closest('article,section,main,aside'))name=null;else name=lm[t];}else if(t==='section'&&accName(cur))name='Region';if(name){var an=accName(cur);return an?name+': '+an:name;}cur=cur.parentElement;hops++;}return null;}function label(el){var map={a:'Link',button:'Button',h1:'Heading h1',h2:'Heading h2',h3:'Heading h3',h4:'Heading h4',h5:'Heading h5',h6:'Heading h6',li:'List item',p:'Paragraph',td:'Table cell',th:'Table header',label:'Form label',figcaption:'Figure caption',blockquote:'Quote'};var self=el.tagName.toLowerCase();var base;if(map[self])base=map[self];else{var cur=el.parentElement,hops=0,found=null;while(cur&&hops<6){var t=cur.tagName.toLowerCase();if(map[t]){found='Text in '+map[t];break;}cur=cur.parentElement;hops++;}base=found||('Text ('+self+')');}var lm=landmark(el);return lm?lm+' › '+base:base;}function px(el){return parseFloat(getComputedStyle(el).fontSize);}function dpr(){return window.devicePixelRatio||1;}function clipCheck(el){var TOL=1;var cur=el,hops=0;while(cur&&cur.nodeType===1&&hops<6&&cur!==document.body){var cs=getComputedStyle(cur);var hiddenX=(cs.overflowX==='hidden'||cs.overflowX==='clip');var hiddenY=(cs.overflowY==='hidden'||cs.overflowY==='clip');var overflowsX=cur.scrollWidth-cur.clientWidth>TOL;var overflowsY=cur.scrollHeight-cur.clientHeight>TOL;var ellipsis=(cs.textOverflow==='ellipsis');if((hiddenX&&overflowsX)||(hiddenY&&overflowsY))return true;if(ellipsis&&overflowsX)return true;if(cs.webkitLineClamp&&cs.webkitLineClamp!=='none'&&overflowsY)return true;cur=cur.parentElement;hops++;}return false;}function hiddenState(el){var cur=el,hops=0;while(cur&&cur.nodeType===1&&hops<8&&cur!==document.body){var cs=getComputedStyle(cur);if(cs.display==='none')return'removed';if(cs.visibility==='hidden'||cs.visibility==='collapse')return'removed';var clip=(cs.clip||'').replace(/\s+/g,'');var isClipRect=/rect\(0(px)?,?0(px)?,?0(px)?,?0(px)?\)/.test(clip)||clip==='rect(1px,1px,1px,1px)';var cp=cs.clipPath||'';var cpHidden=(cp&&cp!=='none'&&/inset\(1?00%|circle\(0/.test(cp));if(isClipRect||cpHidden)return'visually';cur=cur.parentElement;hops++;}return'visible';}var host=document.createElement('div');host.setAttribute('data-rt-ui','1');host.style.cssText='all:initial';document.documentElement.appendChild(host);var sr=host.attachShadow({mode:'open'});var wrap=document.createElement('div');wrap.innerHTML='<style>*{box-sizing:border-box;font-family:system-ui,sans-serif}.panel{position:fixed;top:10px;right:10px;z-index:2147483647;background:#000;color:#fff;font-size:13px;line-height:1.45;padding:0 0 10px;border-radius:8px;max-width:380px;box-shadow:0 4px 16px rgba(0,0,0,.5)}.hdr{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:8px 12px;cursor:move;user-select:none;border-bottom:1px solid #333}.hdr b{font-size:14px}.x{background:#333;color:#fff;border:1px solid #666;width:26px;height:26px;border-radius:4px;cursor:pointer;font-size:14px;line-height:1;flex:none}.body{padding:0 12px}.list{max-height:55vh;overflow:auto}.item{margin:6px 0;padding:6px 8px;background:#161616;border-radius:5px;border:1px solid #333}.item h2{font-size:13px;margin:0 0 3px;color:#fff}.sel{font-family:ui-monospace,monospace;font-size:11px;color:#8ab4ff;margin:0 0 4px;word-break:break-all;white-space:normal}dl{margin:0;display:grid;grid-template-columns:auto 1fr;gap:1px 8px}dt{color:#cfcfcf}dd{margin:0;font-weight:700}.eff{font-size:15px}.warn{color:#ffd23f}.show{margin-top:5px;background:#222;color:#fff;border:1px solid #666;padding:4px 9px;border-radius:4px;cursor:pointer;font-size:12px}.show:focus-visible{outline:2px solid #8ab4ff;outline-offset:1px}.act{width:100%;background:#2563eb;color:#fff;border:0;padding:8px;border-radius:4px;cursor:pointer;font-weight:600;margin-top:8px;font-size:13px}.act:focus-visible{outline:2px solid #fff;outline-offset:1px}.hint{opacity:.9;margin-top:8px}.hover{position:absolute;pointer-events:none;border-radius:2px;z-index:2147483645;box-shadow:0 0 0 2px #000,0 0 0 4px #ffd23f,0 0 0 6px #000}.sel-ovl{position:absolute;pointer-events:none;border-radius:2px;z-index:2147483644;box-shadow:0 0 0 1px #000,0 0 0 3px #fff,0 0 0 4px #000}.flash{position:absolute;pointer-events:none;border-radius:3px;z-index:2147483646;box-shadow:0 0 0 3px rgba(0,0,0,.85),0 0 0 6px rgba(255,255,255,.95),0 0 0 9px rgba(0,0,0,.85);transition:opacity .4s}</style><div class="panel" role="region" aria-label="Resize Text Measurement"><div class="hdr"><b>Resize Text Measurement</b><button class="x" aria-label="Close" title="Close">✕</button></div><div class="body"></div></div>';sr.appendChild(wrap);var panel=sr.querySelector('.panel');var body=sr.querySelector('.body');var hdr=sr.querySelector('.hdr');(function(){var drag=false,ox=0,oy=0;hdr.addEventListener('mousedown',function(e){if(e.target.closest('.x'))return;drag=true;var r=panel.getBoundingClientRect();ox=e.clientX-r.left;oy=e.clientY-r.top;panel.style.right='auto';panel.style.left=r.left+'px';panel.style.top=r.top+'px';e.preventDefault();});window.addEventListener('mousemove',function(e){if(!drag)return;panel.style.left=Math.max(0,e.clientX-ox)+'px';panel.style.top=Math.max(0,e.clientY-oy)+'px';});window.addEventListener('mouseup',function(){drag=false;});})();function esc(s){return(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');}var hoverBox=document.createElement('div');hoverBox.className='hover';hoverBox.style.display='none';sr.appendChild(hoverBox);function posBox(box,el,pad){var r=el.getBoundingClientRect();box.style.left=(r.left+window.scrollX-pad)+'px';box.style.top=(r.top+window.scrollY-pad)+'px';box.style.width=(r.width+pad*2)+'px';box.style.height=(r.height+pad*2)+'px';}function syncSel(){store.items.forEach(function(it){if(it.ovl)posBox(it.ovl,it.el,2);});if(store.phase==='baseline')requestAnimationFrame(syncSel);}function mkSel(el){var o=document.createElement('div');o.className='sel-ovl';sr.appendChild(o);posBox(o,el,2);return o;}function flash(el){var r=el.getBoundingClientRect();var f=document.createElement('div');f.className='flash';f.style.left=(r.left+window.scrollX-4)+'px';f.style.top=(r.top+window.scrollY-4)+'px';f.style.width=(r.width+8)+'px';f.style.height=(r.height+8)+'px';sr.appendChild(f);setTimeout(function(){f.style.opacity='0';},2000);setTimeout(function(){f.remove();},2450);}function onMove(e){if(store.phase!=='baseline'){hoverBox.style.display='none';return;}var path=e.composedPath?e.composedPath():[e.target];if(path.indexOf(host)>-1){hoverBox.style.display='none';return;}var el=e.target;if(!el||!el.textContent||!el.textContent.trim()){hoverBox.style.display='none';return;}hoverBox.style.display='block';posBox(hoverBox,el,2);}function renderBaseline(){body.innerHTML='<div class="hint">Click on texts to capture the baseline (at 100% zoom).</div><div class="list"></div>';var l=body.querySelector('.list');store.items.forEach(function(it,i){var d=document.createElement('div');d.className='item';d.innerHTML='<h2>'+(i+1)+'. '+esc(it.label)+'</h2><p class="sel">'+esc(it.sel)+'</p><dl><dt>Baseline:</dt><dd>'+it.baseCss.toFixed(1)+' px</dd></dl>';l.appendChild(d);});if(store.items.length){var b=document.createElement('button');b.className='act';b.textContent='Baseline complete';b.onclick=function(){store.phase='measure';hoverBox.style.display='none';store.items.forEach(function(it){if(it.ovl){it.ovl.remove();it.ovl=null;}});renderMeasure();};body.appendChild(b);}}function renderMeasure(){body.innerHTML='<div class="list"></div><div class="hint">Enlarge the text, then click “Update”.</div><button class="act">Update</button>';var l=body.querySelector('.list');store.items.forEach(function(it,i){var curCss=px(it.el);var cssF=Math.round(curCss/it.baseCss*100);var zoomF=Math.round(dpr()/it.baseDpr*100);var eff=Math.round(curCss/it.baseCss*(dpr()/it.baseDpr)*1000)/10;var col=eff>=200?'#4ade80':(eff>=150?'#ffd23f':'#ff6b6b');var hs=hiddenState(it.el);var clipped=clipCheck(it.el);var cutTxt,warn=false;if(hs==='removed'){cutTxt='element has been hidden';warn=true;}else if(hs==='visually'){cutTxt='element is visually hidden (clip technique)';warn=true;}else if(clipped){cutTxt='potential text clipping detected';warn=true;}else{cutTxt='check manually';}var cutHtml=warn?'<dd class="warn"><span aria-hidden="true">⚠</span> '+cutTxt+'</dd>':'<dd>'+cutTxt+'</dd>';var d=document.createElement('div');d.className='item';d.innerHTML='<h2>'+(i+1)+'. '+esc(it.label)+'</h2><p class="sel">'+esc(it.sel)+'</p><dl><dt>Baseline:</dt><dd>'+it.baseCss.toFixed(1)+' px</dd><dt>Current:</dt><dd>'+curCss.toFixed(1)+' px</dd><dt>CSS factor:</dt><dd>'+cssF+' %</dd><dt>Zoom factor:</dt><dd>'+zoomF+' %</dd><dt>Effective size:</dt><dd class="eff" style="color:'+col+'">'+eff+' %</dd><dt>Clipped text:</dt>'+cutHtml+'</dl>';var sb=document.createElement('button');sb.className='show';sb.textContent='Show element';sb.setAttribute('aria-label','Show element '+(i+1));sb.onclick=function(){it.el.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(function(){flash(it.el);},350);};d.appendChild(sb);l.appendChild(d);});body.querySelector('.act').onclick=renderMeasure;}function onClick(e){if(store.phase!=='baseline')return;var path=e.composedPath?e.composedPath():[e.target];if(path.indexOf(host)>-1)return;var el=e.target;if(!el||!el.textContent||!el.textContent.trim())return;e.preventDefault();e.stopPropagation();var existing=store.items.find(function(x){return x.el===el;});if(existing){existing.baseCss=px(el);existing.baseDpr=dpr();}else{store.items.push({el:el,baseCss:px(el),baseDpr:dpr(),sel:cssPath(el),label:label(el),ovl:mkSel(el)});}renderBaseline();}document.addEventListener('click',onClick,true);document.addEventListener('mousemove',onMove,true);requestAnimationFrame(syncSel);function cleanup(){document.removeEventListener('click',onClick,true);document.removeEventListener('mousemove',onMove,true);host.remove();window.__rt_active=0;}panel.querySelector('.x').onclick=cleanup;window.__rt_cleanup=cleanup;renderBaseline();})();
